/* Templates of the generator's outputs. The build fills them in and Prettier formats them. */

export const HEADER =
    '/* Generated by `npm run icons` from icon-sources.json; edit the manifest, not this file. */';

function pascalCase(name) {
    return name
        .split('-')
        .map((part) => `${part[0].toUpperCase()}${part.slice(1)}`)
        .join('');
}

function componentOf(name) {
    return `${pascalCase(name)}Icon`;
}

/** Part the long `d` of a source into concatenation so no line outruns the lint. */
function chunksOf(d) {
    const parts = [];
    let current = '';

    for (const token of d.split(' ')) {
        if (current !== '' && `${current} ${token}`.length > 76) {
            parts.push(`${current} `);
            current = token;
            continue;
        }

        current = current === '' ? token : `${current} ${token}`;
    }

    if (current !== '') {
        parts.push(current);
    }

    return parts;
}

export function componentSource(name, paths, mirrored = false) {
    const component = componentOf(name);
    const drawn = paths
        .map((path) => {
            const fillRule = path.fillRule === undefined ? '' : ` fillRule="${path.fillRule}"`;
            const clipRule = path.clipRule === undefined ? '' : ` clipRule="${path.clipRule}"`;
            const parts = chunksOf(path.d);
            const d =
                parts.length === 1
                    ? `d="${parts[0]}"`
                    : `d={${parts.map((part) => `'${part}'`).join(' +\n')}}`;

            return `                <path${fillRule}${clipRule} ${d} />`;
        })
        .join('\n');

    return `${HEADER}
import type { IconAppearanceProps } from './icon-appearance.js';
import { IconFrame } from './icon-frame.js';

/** Represents the ${name.replaceAll('-', ' ')} icon. */
export function ${component}(props: IconAppearanceProps) {
    return (
        <IconFrame {...props}${mirrored ? ' mirrored' : ''}>
${drawn}
        </IconFrame>
    );
}
`;
}

export function namesSource(names) {
    const values = names.map((name) => `    '${name}',`).join('\n');

    return `${HEADER}
export const ICON_NAMES = [
${values}
] as const;

export type IconName = (typeof ICON_NAMES)[number];
`;
}

export function registrySource(names) {
    const imports = names
        .map((name) => `import { ${componentOf(name)} } from './${name}.js';`)
        .join('\n');
    const entries = names.map((name) => `    '${name}': ${componentOf(name)},`).join('\n');

    return `${HEADER}
import type { IconComponent } from './icon-appearance.js';

${imports}

import type { IconName } from './icon-name.js';

export const ICONS = {
${entries}
} satisfies Record<IconName, IconComponent>;
`;
}

export function barrelSource(names) {
    const components = names
        .map((name) => `export { ${componentOf(name)} } from './${name}.js';`)
        .join('\n');

    return `${HEADER}
export { type IconComponent } from './icon-appearance.js';
${components}
export { Icon } from './icon.js';
export { type IconName } from './icon-name.js';
`;
}

export function registryTestSource(names) {
    const registry = names.join(' ');

    return `${HEADER}
import { render } from '@testing-library/react';
import type { ComponentType } from 'react';
import { describe, expect, it } from 'vitest';

import * as glyph from '../src/index.js';

type IconComponent = ComponentType<{ size?: 'lg' | 'md' | 'sm' }>;

const NAMES = \`${registry}\`.split(' ');

function componentOf(name: string): string {
    return (
        name
            .split('-')
            .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
            .join('') + 'Icon'
    );
}

describe('the generated icons', () => {
    for (const name of NAMES) {
        const Icon = glyph[componentOf(name) as keyof typeof glyph] as IconComponent;

        it(\`draws the \${name} icon hidden on every size of the scale\`, () => {
            for (const size of ['sm', 'md', 'lg'] as const) {
                const { container, unmount } = render(<Icon size={size} />);
                const svg = container.querySelector('svg');

                expect(svg?.getAttribute('aria-hidden')).toBe('true');
                expect(svg?.getAttribute('data-part')).toBe('icon');
                expect(svg?.getAttribute('height')).toBe(
                    ({ lg: '24', md: '16', sm: '14' } as const)[size],
                );
                expect(svg?.querySelector('path')).not.toBeNull();
                unmount();
            }
        });
    }
});
`;
}
